import importlib
import shutil

modules = ["pypdf", "PyPDF2", "fitz", "pdfplumber", "reportlab", "pikepdf", "pypdfium2"]
for m in modules:
    try:
        importlib.import_module(m)
        print(f"module {m}: OK")
    except Exception as e:
        print(f"module {m}: missing ({type(e).__name__})")

for tool in ["qpdf", "pdftk", "gs", "pdftotext"]:
    path = shutil.which(tool)
    print(f"tool {tool}: {path if path else 'missing'}")

